/** The database: the `devsync` schema's tables and the migrations the host applies. */
import { fileURLToPath } from "node:url";

export * from "./schema";

/**
 * DevSync's SQL migrations, generated by drizzle-kit from `schema.ts`: the host applies them after
 * its own, with the journal in `devsync.__drizzle_migrations` (docs/host.md).
 */
export const migrations = {
  folder: fileURLToPath(new URL("../../migrations", import.meta.url)),
  schema: "devsync",
} as const;
